-- BanManager's tables (the DDL of its H2/MySQL schema, as the plugin creates them): quoted,
-- lower case table names and camelCase columns; times are epoch seconds, expires/expired 0 is
-- permanent (INT columns: the far future used here is just below 2038). Only the tables the importer reads, and two it knowingly ignores (name_bans,
-- ip_range_bans).
CREATE TABLE "bm_players" (
  "id" BINARY(16) NOT NULL,
  "name" CHARACTER VARYING(16) NOT NULL,
  "ip" VARBINARY(16) NOT NULL,
  "lastSeen" INT NOT NULL
);
CREATE TABLE "bm_player_bans" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_player_ban_records" (
  "id" INT NOT NULL,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "expired" BIGINT NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "pastActor_id" BINARY(16) NOT NULL,
  "pastCreated" INT NOT NULL,
  "created" INT NOT NULL,
  "createdReason" CHARACTER VARYING(255) NOT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_ip_bans" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "ip" VARBINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_ip_ban_records" (
  "id" INT NOT NULL,
  "ip" VARBINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "expired" BIGINT NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "pastActor_id" BINARY(16) NOT NULL,
  "pastCreated" INT NOT NULL,
  "created" INT NOT NULL,
  "createdReason" CHARACTER VARYING(255) NOT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_player_mutes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "soft" TINYINT DEFAULT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_player_mute_records" (
  "id" INT NOT NULL,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "expired" BIGINT NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "pastActor_id" BINARY(16) NOT NULL,
  "pastCreated" INT NOT NULL,
  "created" INT NOT NULL,
  "createdReason" CHARACTER VARYING(255) NOT NULL,
  "soft" TINYINT DEFAULT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_ip_mutes" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "ip" VARBINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "soft" TINYINT DEFAULT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_ip_mute_records" (
  "id" INT NOT NULL,
  "ip" VARBINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "expired" BIGINT NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "pastActor_id" BINARY(16) NOT NULL,
  "pastCreated" INT NOT NULL,
  "created" INT NOT NULL,
  "createdReason" CHARACTER VARYING(255) NOT NULL,
  "soft" TINYINT DEFAULT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_player_warnings" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "expires" INT NOT NULL,
  "read" TINYINT DEFAULT NULL,
  "points" double DEFAULT NULL
);
CREATE TABLE "bm_player_kicks" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "player_id" BINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL
);
CREATE TABLE "bm_name_bans" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "name" CHARACTER VARYING(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "silent" TINYINT DEFAULT NULL
);
CREATE TABLE "bm_ip_range_bans" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY,
  "fromIp" VARBINARY(16) NOT NULL,
  "toIp" VARBINARY(16) NOT NULL,
  "reason" CHARACTER VARYING(255) NOT NULL,
  "actor_id" BINARY(16) NOT NULL,
  "created" INT NOT NULL,
  "updated" INT NOT NULL,
  "expires" INT NOT NULL,
  "silent" TINYINT DEFAULT NULL
);

